//! Pollard rho with full automorphism-orbit folding on j=0 curves.
//!
//! **Specifically targets secp256k1.**  Bitcoin's curve has CM by
//! the Eisenstein integers `Z[ω]` where `ω = (−1 + √−3)/2`, which
//! gives `Aut(E) = Z/6Z` (six automorphisms generated by negation
//! and the GLV endomorphism).  Walking on orbits of the whole group
//! instead of on points divides the expected number of rho steps by
//! `√6 ≈ 2.45`: `√2` from the negation map, which every curve has,
//! and a further `√3` from the order-3 endomorphism that only
//! `j = 0` curves have.
//!
//! # Prior art
//!
//! This module claims no novelty.  The `√|Aut(E)|` speedup, and the
//! `√6` for `j = 0` in particular, is a late-1990s result:
//!
//! - Wiener and Zuccherato, *Faster attacks on elliptic curve
//!   cryptosystems* (SAC 1998): the negation map, and the Frobenius
//!   on subfield curves, as equivalence classes for rho.
//! - Duursma, Gaudry and Morain, *Speeding up the discrete log
//!   computation on curves with automorphisms* (ASIACRYPT 1999):
//!   the general `√m` speedup for an automorphism group of order
//!   `m`, with `j = 0` (`m = 6`) and `j = 1728` (`m = 4`) as the
//!   worked elliptic cases.
//! - Gallant, Lambert and Vanstone, *Improving the parallelized
//!   Pollard lambda search on anomalous binary curves* (Math. Comp.
//!   2000): walking on canonical class representatives with
//!   distinguished points, and the fruitless short cycles that
//!   folding introduces.
//! - Bos, Kleinjung and Lenstra, *On the use of the negation map in
//!   the Pollard rho method* (ANTS 2010), and Bernstein, Lange and
//!   Schwabe, *On the correct use of the negation map in the Pollard
//!   rho method* (PKC 2011): detecting and escaping those cycles.
//!
//! What this file provides is an implementation of the full 6-fold
//! folding in the same framework as the other `cryptanalysis`
//! modules, with the canonicalisation, planted-DLP and speedup-ratio
//! tests described below.  The GPU implementation of the same walk
//! is `gpu/ecc/rho.cuh` with `fold = 6`.  A measured ratio between
//! folded and unfolded walks here checks that the implementation
//! realises the known `√6`; it is not evidence of anything beyond it.
//!
//! # Mathematical structure (j = 0 curves)
//!
//! For `E: y² = x³ + b` over `F_p` with `p ≡ 1 (mod 3)`:
//!
//! - **Cube root of unity**: `β ∈ F_p` with `β³ ≡ 1, β ≠ 1` exists
//!   and corresponds to `ω ∈ Z[ω]` acting on E as
//!   `[ω]: (x, y) → (β·x, y)` — the GLV endomorphism.  As an integer
//!   action, `ω` corresponds to multiplication by `λ ∈ Z/n` where
//!   `λ³ ≡ 1 (mod n), λ ≠ 1`.
//! - **Negation**: `[−1]: (x, y) → (x, −y)`.  Corresponds to
//!   multiplication by `−1 mod n`.
//! - **Aut(E)** is generated by `[ω]` and `[−1]`, has 6 elements:
//!   `{1, ω, ω², −1, −ω, −ω²}`.  Acts on integers in `Z/n` by
//!   multiplication by `{1, λ, λ², −1, −λ, −λ²}`.
//!
//! # Folded rho: the core idea
//!
//! Define `R(P)` = the lex-smallest point in `{α·P : α ∈ Aut(E)}`.
//! This is a 6-to-1 map `E → E/Aut(E)`.  Pollard rho on the
//! quotient effectively walks a set of size `n/6`, so the expected
//! number of steps to the first repeated class is
//! `√(π(n/6)/2) = √(πn/12) = (1/√6) · √(πn/2)`, against `√(πn/2)`
//! for the walk on `E` itself.  This solver detects the repeat with
//! Floyd's tortoise and hare, which stops after about `1.03 · √(n/6)`
//! iterations of one tortoise step plus two hare steps (Knuth,
//! TAOCP vol. 2, §3.1); `FoldedRhoSolution::effective_rho_factor`
//! reports the measured multiple of `√(n/6)`.
//!
//! Per-step bookkeeping: each walker tracks `(current_point, a, b)`
//! such that `current_point = a·G + b·Q`.  When two walkers with
//! states `(P_1, a_1, b_1)` and `(P_2, a_2, b_2)` collide on the
//! canonical representative `R(P_1) = R(P_2)`, there exist
//! `α_1, α_2 ∈ Aut(E)` such that `α_1·P_1 = α_2·P_2`.  Setting
//! `γ = α_1⁻¹·α_2` (an element of `Aut(E)`) and `μ_γ` its action
//! as integer mod `n`:
//!
//! ```text
//! P_1 = γ · P_2
//! a_1·G + b_1·Q = μ_γ · (a_2·G + b_2·Q)
//! d = (μ_γ · a_2 − a_1) · (b_1 − μ_γ · b_2)⁻¹  (mod n)
//! ```
//!
//! provided `b_1 ≢ μ_γ · b_2 (mod n)`.  When the divisor is zero
//! we hit a sterile collision (an "automorphism-cycle" rather than
//! a useful relation); restart from a fresh `(a₀, b₀)`.
//!
//! # Test strategy
//!
//! - Canonicalisation correctness: for any `P` and any `α ∈ Aut`,
//!   `R(α·P) = R(P)`.
//! - Planted-DLP recovery on a toy j=0 curve.
//! - Empirical speedup: count walk steps for folded vs unfolded rho
//!   on the same DLP, expect ratio ≈ `√6`.

use crate::cryptanalysis::cga_hnc::{
    add_mod_word, mul_mod_word, pt_add, pt_double, pt_scalar_mul, reduced_word, sub_mod_word,
    word_modulus, Pt2,
};
use crate::utils::mod_inverse;
use num_bigint::{BigInt, RandBigInt, ToBigInt};
use num_integer::Integer;
use num_traits::{One, Signed, Zero};
use rand::rngs::StdRng;
use rand::SeedableRng;

/// Pre-computed CM-action data for a j=0 curve.
#[derive(Clone, Debug)]
pub struct J0CurveAut {
    /// Field characteristic `p` with `p ≡ 1 (mod 3)`.
    pub p: BigInt,
    /// Curve coefficient `a` (= 0 for j=0).
    pub a: BigInt,
    /// Curve coefficient `b` (≠ 0 for j=0).
    pub b: BigInt,
    /// Group order `n` of `⟨G⟩` ⊂ `E(F_p)`.
    pub n: BigInt,
    /// Primitive cube root of 1 mod p: `β³ ≡ 1, β ≠ 1`.
    pub beta: BigInt,
    /// Primitive cube root of 1 mod n: `λ³ ≡ 1, λ ≠ 1`.  When this
    /// doesn't exist (n has no cube-root structure) we fall back
    /// to using `n − λ_0 − 1` for some chosen `λ_0`; in practice
    /// for a j=0 curve over `F_p` with `p ≡ 1 mod 3`, n satisfies
    /// `λ³ ≡ 1 (mod n)` automatically.
    pub lambda: BigInt,
}

/// One element of `Aut(E) = Z/6Z` for j=0 curves.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AutElt {
    /// `[1]` — identity
    Id,
    /// `[ω]` — GLV endomorphism
    Omega,
    /// `[ω²]`
    Omega2,
    /// `[−1]` — negation
    Neg,
    /// `[−ω]`
    NegOmega,
    /// `[−ω²]`
    NegOmega2,
}

impl AutElt {
    /// All 6 automorphisms in canonical order.
    pub const ALL: [AutElt; 6] = [
        AutElt::Id,
        AutElt::Omega,
        AutElt::Omega2,
        AutElt::Neg,
        AutElt::NegOmega,
        AutElt::NegOmega2,
    ];

    /// `α^{-1}` for `α ∈ Aut(E)`.
    pub fn inv(self) -> AutElt {
        match self {
            AutElt::Id => AutElt::Id,
            AutElt::Omega => AutElt::Omega2,
            AutElt::Omega2 => AutElt::Omega,
            AutElt::Neg => AutElt::Neg,
            AutElt::NegOmega => AutElt::NegOmega2,
            AutElt::NegOmega2 => AutElt::NegOmega,
        }
    }

    /// Composition: `(α · β)(P) = α(β(P))`.
    pub fn compose(self, other: AutElt) -> AutElt {
        // Encode each as (sign, omega-power) ∈ {±1} × Z/3:
        //   Id → (+, 0), Omega → (+, 1), Omega2 → (+, 2)
        //   Neg → (−, 0), NegOmega → (−, 1), NegOmega2 → (−, 2)
        let (s1, o1) = self.encode();
        let (s2, o2) = other.encode();
        AutElt::decode(s1 * s2, (o1 + o2) % 3)
    }

    fn encode(self) -> (i32, u32) {
        match self {
            AutElt::Id => (1, 0),
            AutElt::Omega => (1, 1),
            AutElt::Omega2 => (1, 2),
            AutElt::Neg => (-1, 0),
            AutElt::NegOmega => (-1, 1),
            AutElt::NegOmega2 => (-1, 2),
        }
    }

    fn decode(sign: i32, omega_pow: u32) -> AutElt {
        match (sign, omega_pow) {
            (1, 0) => AutElt::Id,
            (1, 1) => AutElt::Omega,
            (1, 2) => AutElt::Omega2,
            (-1, 0) => AutElt::Neg,
            (-1, 1) => AutElt::NegOmega,
            (-1, 2) => AutElt::NegOmega2,
            _ => unreachable!(),
        }
    }

    /// Action on integers mod `n`: returns the multiplier
    /// `μ ∈ Z/n` such that for any point `P`, `α(P) = μ · P`.
    pub fn integer_action(self, lambda: &BigInt, n: &BigInt) -> BigInt {
        let l_sq = (lambda * lambda) % n;
        let one = BigInt::one();
        let raw = match self {
            AutElt::Id => one.clone(),
            AutElt::Omega => lambda.clone(),
            AutElt::Omega2 => l_sq.clone(),
            AutElt::Neg => -one.clone(),
            AutElt::NegOmega => -lambda.clone(),
            AutElt::NegOmega2 => -l_sq.clone(),
        };
        ((raw % n) + n) % n
    }
}

/// `x mod p` in `[0, p)`: one remainder and a conditional add for the
/// positive moduli used here, the textbook `((x % p) + p) % p` (and its
/// behaviour) for any other `p`.  See `cga_hnc`'s copy.
fn mod_pos(x: BigInt, p: &BigInt) -> BigInt {
    if p.is_positive() {
        let r = x % p;
        if r.is_negative() {
            r + p
        } else {
            r
        }
    } else {
        ((x % p) + p) % p
    }
}

/// Apply `α ∈ Aut(E)` to a point.
pub fn apply_aut(point: &Pt2, alpha: AutElt, aut: &J0CurveAut) -> Pt2 {
    let (sign, omega_pow) = alpha.encode();
    let beta_pow = match omega_pow {
        0 => BigInt::one(),
        1 => aut.beta.clone(),
        2 => mod_pos(&aut.beta * &aut.beta, &aut.p),
        _ => unreachable!(),
    };
    let with_omega = match point {
        Pt2::Inf => Pt2::Inf,
        Pt2::Aff(x, y) => {
            let x_new = mod_pos(x * &beta_pow, &aut.p);
            Pt2::Aff(x_new, y.clone())
        }
    };
    if sign == 1 {
        with_omega
    } else {
        // Negate.
        match with_omega {
            Pt2::Inf => Pt2::Inf,
            Pt2::Aff(x, y) => Pt2::Aff(x, mod_pos(-y, &aut.p)),
        }
    }
}

/// Compare two points by `(x, y)` lexicographically.  `Inf` sorts
/// last (treated as ∞).
fn compare_pt(a: &Pt2, b: &Pt2) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    match (a, b) {
        (Pt2::Inf, Pt2::Inf) => Ordering::Equal,
        (Pt2::Inf, _) => Ordering::Greater,
        (_, Pt2::Inf) => Ordering::Less,
        (Pt2::Aff(x1, y1), Pt2::Aff(x2, y2)) => match x1.cmp(x2) {
            Ordering::Equal => y1.cmp(y2),
            other => other,
        },
    }
}

/// Canonical representative of `P` under `Aut(E)`-orbit, plus the
/// automorphism that maps `P` to its canonical form
/// (i.e. `α · P = canonical`).  Returns `(canonical, α)`.
pub fn canonical_form(point: &Pt2, aut: &J0CurveAut) -> (Pt2, AutElt) {
    canonical_form_with(point, aut, &beta_squared(aut))
}

/// `β² mod p`, the `x`-multiplier of `[ω²]` and `[−ω²]`.
fn beta_squared(aut: &J0CurveAut) -> BigInt {
    mod_pos(&aut.beta * &aut.beta, &aut.p)
}

/// [`canonical_form`] with `β² mod p` supplied by the caller, so that a
/// walk canonicalising every point computes it once per solve rather
/// than twice per point.
///
/// The six images of `(x, y)` share three `x`-coordinates (`x`, `β·x`,
/// `β²·x`, reduced) and two `y`-coordinates (`y` and `−y mod p`), so
/// they are built from those five values instead of by six calls to
/// [`apply_aut`].  They are visited in [`AutElt::ALL`] order, `[ω^k]`
/// before `[−ω^k]`, and the first strict minimum is kept, so ties break
/// exactly as [`canonical_form`] breaks them by applying each element in
/// turn.  `y` is used as given on the `[ω^k]` side, as [`apply_aut`]
/// uses it.
fn canonical_form_with(point: &Pt2, aut: &J0CurveAut, beta_sq: &BigInt) -> (Pt2, AutElt) {
    let (x, y) = match point {
        Pt2::Inf => return (Pt2::Inf, AutElt::Id),
        Pt2::Aff(x, y) => (x, y),
    };
    if let Some(canon) = canonical_form_word(x, y, aut, beta_sq) {
        return canon;
    }
    let p = &aut.p;
    let mut xs = [
        mod_pos(x.clone(), p),
        mod_pos(x * &aut.beta, p),
        mod_pos(x * beta_sq, p),
    ];
    let neg_y = mod_pos(-y, p);
    let ys = [y, &neg_y];
    // Index `k` of `AutElt::ALL` has ω-power `k % 3` and sign `k / 3`.
    let mut best = 0;
    for k in 1..6 {
        if (&xs[k % 3], ys[k / 3]) < (&xs[best % 3], ys[best / 3]) {
            best = k;
        }
    }
    let y_best = if best < 3 { y.clone() } else { neg_y };
    let x_best = std::mem::take(&mut xs[best % 3]);
    (Pt2::Aff(x_best, y_best), AutElt::ALL[best])
}

/// [`canonical_form_with`] on words, when `p`, the coordinates, `β` and
/// `β²` are all reduced residues below 2⁶⁴ (see `cga_hnc`'s word-sized
/// fields).  Reduced inputs make the `[ω^k]` images' `y` the same
/// residue as the `BigInt` path's clone, so both return the same point.
fn canonical_form_word(
    x: &BigInt,
    y: &BigInt,
    aut: &J0CurveAut,
    beta_sq: &BigInt,
) -> Option<(Pt2, AutElt)> {
    let p = word_modulus(&aut.p)?;
    let (x, y) = (reduced_word(x, p)?, reduced_word(y, p)?);
    let (beta, beta_sq) = (reduced_word(&aut.beta, p)?, reduced_word(beta_sq, p)?);
    let xs = [x, mul_mod_word(x, beta, p), mul_mod_word(x, beta_sq, p)];
    let ys = [y, sub_mod_word(0, y, p)];
    let mut best = 0;
    for k in 1..6 {
        if (xs[k % 3], ys[k / 3]) < (xs[best % 3], ys[best / 3]) {
            best = k;
        }
    }
    let canon = Pt2::Aff(BigInt::from(xs[best % 3]), BigInt::from(ys[best / 3]));
    Some((canon, AutElt::ALL[best]))
}

/// `v` and `n` as words, when `n` is a word modulus and `v` a reduced
/// residue: the case of every exponent the walk carries on a word-sized
/// group, since each is either drawn from `[0, n)` or reduced mod `n`.
fn word_exponent(v: &BigInt, n: &BigInt) -> Option<(u64, u64)> {
    let n = word_modulus(n)?;
    Some((reduced_word(v, n)?, n))
}

/// `(v + 1) mod n` in `[0, n)`: on words when [`word_exponent`] allows,
/// else by `mod_pos`, which gives the same residue.
fn increment_mod(v: &BigInt, n: &BigInt) -> BigInt {
    match word_exponent(v, n) {
        Some((v, n)) => BigInt::from(add_mod_word(v, 1, n)),
        None => mod_pos(v + BigInt::one(), n),
    }
}

/// `2·v mod n` in `[0, n)`, likewise.
fn double_mod(v: &BigInt, n: &BigInt) -> BigInt {
    match word_exponent(v, n) {
        Some((v, n)) => BigInt::from(add_mod_word(v, v, n)),
        None => mod_pos(v * BigInt::from(2), n),
    }
}

/// The walk's partition index of a canonical point: the last byte of
/// its `x`-coordinate's big-endian two's-complement encoding, mod 3
/// (`Inf` is bucket 0).  Reads that byte off the lowest limb instead of
/// allocating the encoding; a negative coordinate, which only a
/// non-positive modulus could produce, gets the byte its two's
/// complement ends in, as the encoding would give it.
fn walk_bucket(canon: &Pt2) -> u8 {
    match canon {
        Pt2::Inf => 0,
        Pt2::Aff(cx, _) => {
            let low = cx.magnitude().iter_u64_digits().next().unwrap_or(0) as u8;
            let last = if cx.is_negative() {
                low.wrapping_neg()
            } else {
                low
            };
            (last as u32 % 3) as u8
        }
    }
}

// ── Folded rho ────────────────────────────────────────────────────────────

#[derive(Clone, Debug)]
pub struct FoldedRhoSolution {
    /// Recovered discrete log `d` such that `Q = d·G`.
    pub d: BigInt,
    /// Number of walk steps (each = one tortoise step + two hare steps).
    pub iterations: u64,
    /// Total restarts due to sterile collisions.
    pub restarts: u32,
    /// Effective rho factor — `iterations / √(n/6)`.  `iterations`
    /// counts Floyd iterations, which stop at the first multiple of
    /// the cycle length past the tail, so this should approach about
    /// 1.03 in expectation (Knuth, TAOCP vol. 2, §3.1; simulated on
    /// random mappings of 2^11–2^15 points: 1.02–1.04).  The expected
    /// number of steps to the first repeated class, `√(π/2) ≈ 1.25`
    /// times `√(n/6)`, is a different quantity.  Reported for
    /// empirical speedup measurement.
    pub effective_rho_factor: f64,
}

#[derive(Clone, Debug)]
pub struct FoldedRhoOptions {
    pub max_iterations: u64,
    pub max_restarts: u32,
    pub seed: Option<u64>,
}

impl Default for FoldedRhoOptions {
    fn default() -> Self {
        Self {
            max_iterations: 1u64 << 24,
            max_restarts: 16,
            seed: None,
        }
    }
}

/// Pollard rho with full 6-fold automorphism folding for j=0 curves.
///
/// On collision, recovers `d` from the collision relation modulo
/// the relevant `Aut(E)` element discovered via canonicalisation.
pub fn aut_folded_rho_dlp(
    g: &Pt2,
    h: &Pt2,
    aut: &J0CurveAut,
    opts: &FoldedRhoOptions,
) -> Result<FoldedRhoSolution, &'static str> {
    let n = &aut.n;
    if n.is_zero() || n.is_one() {
        return Err("group order must be ≥ 2");
    }

    let mut rng: StdRng = match opts.seed {
        Some(s) => StdRng::seed_from_u64(s),
        None => StdRng::seed_from_u64(0xFADE_F00D_BABE_BEEFu64),
    };

    let mut total_iters: u64 = 0;
    let curve_a = &aut.a;
    let p_mod = &aut.p;
    let beta_sq = beta_squared(aut);
    let canon = |x: &Pt2| canonical_form_with(x, aut, &beta_sq);

    // Step function: deterministic 3-bucket walk based on partition
    // of CANONICAL form's x coordinate.  Tracks (point, a, b) such
    // that point = a·g + b·h.  The caller passes `x`'s canonical form:
    // the collision check has already computed it for the tortoise and
    // the hare, so each Floyd iteration canonicalises three points (the
    // two new ones and the hare's midpoint), not five.
    let step = |x: &Pt2, x_canon: &Pt2, a: &BigInt, b: &BigInt| -> (Pt2, BigInt, BigInt) {
        match walk_bucket(x_canon) {
            0 => {
                let nx = pt_add(x, g, curve_a, p_mod);
                let na = increment_mod(a, n);
                (nx, na, b.clone())
            }
            1 => {
                let nx = pt_add(x, h, curve_a, p_mod);
                let nb = increment_mod(b, n);
                (nx, a.clone(), nb)
            }
            _ => {
                let nx = pt_double(x, curve_a, p_mod);
                let na = double_mod(a, n);
                let nb = double_mod(b, n);
                (nx, na, nb)
            }
        }
    };

    for restart in 0..=opts.max_restarts {
        // Initial state for this restart.
        let (a0, b0) = if restart == 0 {
            (BigInt::one(), BigInt::zero())
        } else {
            (
                rng.gen_bigint_range(&BigInt::zero(), n),
                rng.gen_bigint_range(&BigInt::zero(), n),
            )
        };
        let pow_a = pt_scalar_mul(g, &a0, curve_a, p_mod);
        let pow_b = pt_scalar_mul(h, &b0, curve_a, p_mod);
        let x0 = pt_add(&pow_a, &pow_b, curve_a, p_mod);

        let (mut t_canon, _) = canon(&x0);
        let mut h_canon = t_canon.clone();
        let mut t = x0.clone();
        let mut t_a = a0.clone();
        let mut t_b = b0.clone();
        let mut h_pt = x0;
        let mut h_a = a0;
        let mut h_b = b0;

        let mut iters: u64 = 0;
        let mut sterile = false;

        while iters < opts.max_iterations {
            // Tortoise: 1 step.
            let (nt, na, nb) = step(&t, &t_canon, &t_a, &t_b);
            t = nt;
            t_a = na;
            t_b = nb;

            // Hare: 2 steps.
            let (nh, nha, nhb) = step(&h_pt, &h_canon, &h_a, &h_b);
            h_pt = nh;
            h_a = nha;
            h_b = nhb;
            let (h_mid_canon, _) = canon(&h_pt);
            let (nh, nha, nhb) = step(&h_pt, &h_mid_canon, &h_a, &h_b);
            h_pt = nh;
            h_a = nha;
            h_b = nhb;

            iters += 1;
            total_iters += 1;

            // Collision detection: compare CANONICAL forms.  They are
            // kept for the next iteration's steps.
            let t_alpha;
            let h_alpha;
            (t_canon, t_alpha) = canon(&t);
            (h_canon, h_alpha) = canon(&h_pt);
            if compare_pt(&t_canon, &h_canon) == std::cmp::Ordering::Equal {
                // Both walkers landed in the same Aut-orbit.
                // γ = t_alpha⁻¹ · h_alpha maps t (after canon) to h (after canon).
                // Equivalently, γ · t = h (as raw points), since
                //   t_canon = t_alpha · t  ⇔  t = t_alpha⁻¹ · t_canon
                //   h_canon = h_alpha · h  ⇔  h = h_alpha⁻¹ · h_canon = h_alpha⁻¹ · t_canon
                //   ⇒ h = h_alpha⁻¹ · t_alpha · t = (h_alpha⁻¹ · t_alpha) · t
                let gamma = h_alpha.inv().compose(t_alpha);
                let mu = gamma.integer_action(&aut.lambda, n);
                // Recovery: a_h·G + b_h·Q = μ · (a_t·G + b_t·Q)
                //   ⇒ (a_h − μ·a_t)·G + (b_h − μ·b_t)·Q = O
                //   ⇒ d = (μ·a_t − a_h) · (b_h − μ·b_t)⁻¹ (mod n)
                let lhs = mod_pos((&mu * &t_a) - &h_a, n);
                let rhs = mod_pos(&h_b - (&mu * &t_b), n);
                if rhs.is_zero() {
                    sterile = true;
                    break;
                }
                let g_factor = rhs.gcd(n);
                if !g_factor.is_one() {
                    sterile = true;
                    break;
                }
                let rhs_u = rhs.to_biguint().expect("non-zero positive after mod_pos");
                let n_u = n.to_biguint().expect("n positive");
                let rhs_inv_u = mod_inverse(&rhs_u, &n_u)
                    .ok_or("rhs not invertible despite gcd=1 — internal inconsistency")?;
                let rhs_inv = rhs_inv_u.to_bigint().expect("biguint→bigint");
                let d = mod_pos(&lhs * &rhs_inv, n);
                // Verify: d·G = h.
                let check = pt_scalar_mul(g, &d, curve_a, p_mod);
                if compare_pt(&check, h) == std::cmp::Ordering::Equal {
                    // Empirical rho factor.
                    let n_f64 = bigint_to_f64(n);
                    let expected = (n_f64 / 6.0).sqrt();
                    let factor = total_iters as f64 / expected;
                    return Ok(FoldedRhoSolution {
                        d,
                        iterations: total_iters,
                        restarts: restart,
                        effective_rho_factor: factor,
                    });
                }
                // The recovered d didn't verify — likely a sterile/aliased
                // collision.  Restart.
                sterile = true;
                break;
            }
        }
        if !sterile {
            return Err("rho exceeded max_iterations without finding a collision");
        }
    }
    Err("aut-folded rho exhausted max_restarts on sterile collisions")
}

fn bigint_to_f64(x: &BigInt) -> f64 {
    let bits = x.bits() as i32;
    if bits < 53 {
        let bytes = x.to_signed_bytes_be();
        let mut v: u64 = 0;
        for b in bytes.iter() {
            v = (v << 8) | (*b as u64);
        }
        v as f64
    } else {
        2f64.powi(bits)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use rand::Rng;

    /// Search for a j=0 curve over `F_p` whose order is **prime
    /// and ≡ 1 (mod 3)** — exactly the curves where the full
    /// `Aut(E) = Z/6Z` acts faithfully on a single cyclic subgroup
    /// (the whole group, since order is prime).  This is the
    /// regime where aut-folded rho's `√6` speedup is mathematically
    /// valid.
    fn find_j0_prime_order_curve(p: u64) -> Option<(u64, u64)> {
        if p % 3 != 1 {
            return None;
        }
        for b in 1..p {
            let n = brute_count_points(0, b, p);
            if n % 3 == 1 && is_prime_u64(n) {
                return Some((b, n));
            }
        }
        None
    }

    fn is_prime_u64(n: u64) -> bool {
        if n < 2 {
            return false;
        }
        if n < 4 {
            return true;
        }
        if n.is_multiple_of(2) {
            return false;
        }
        let mut d = 3u64;
        while d.saturating_mul(d) <= n {
            if n.is_multiple_of(d) {
                return false;
            }
            d += 2;
        }
        true
    }

    fn brute_count_points(a: u64, b: u64, p: u64) -> u64 {
        let mut count = 1u64; // infinity
        for x in 0..p {
            let rhs = (((x as u128) * (x as u128) % p as u128) * (x as u128) % p as u128
                + (a as u128) * (x as u128) % p as u128
                + b as u128)
                % p as u128;
            let rhs = rhs as u64;
            if rhs == 0 {
                count += 1;
                continue;
            }
            // Euler: rhs^((p-1)/2).
            let mut r = 1u128;
            let mut base = rhs as u128;
            let mut exp = (p - 1) / 2;
            while exp > 0 {
                if exp & 1 == 1 {
                    r = r * base % p as u128;
                }
                base = base * base % p as u128;
                exp >>= 1;
            }
            if r == 1 {
                count += 2;
            }
        }
        count
    }

    /// Find a primitive cube root of unity mod m.
    fn primitive_cube_root_mod(m: u64) -> Option<u64> {
        for x in 2..m {
            let mut acc: u128 = 1;
            let xb = x as u128;
            for _ in 0..3 {
                acc = (acc * xb) % m as u128;
            }
            if acc == 1 && x != 1 {
                return Some(x);
            }
        }
        None
    }

    /// Build a `J0CurveAut` for a known good `(p, b, n, β, λ)` combo.
    /// Used by all tests; see `find_j0_prime_order_curve` for how to
    /// produce one fresh.  We use `(p=43, b=8, n=31)` — found by
    /// brute search — as a stable test fixture.
    fn good_aut() -> J0CurveAut {
        // Candidate: p = 43, b = 1, n = ?  Brute-search at construction.
        let p_u = 43u64;
        let (b_u, n_u) = find_j0_prime_order_curve(p_u).expect("j=0 prime-order curve at p=43");
        // p ≡ 1 mod 3, n is prime ≡ 1 mod 3.
        let beta_u = primitive_cube_root_mod(p_u).expect("β exists since p ≡ 1 mod 3");
        let lambda_u = primitive_cube_root_mod(n_u).expect("λ exists since n is prime ≡ 1 mod 3");
        J0CurveAut {
            p: BigInt::from(p_u),
            a: BigInt::from(0),
            b: BigInt::from(b_u),
            n: BigInt::from(n_u),
            beta: BigInt::from(beta_u),
            lambda: BigInt::from(lambda_u),
        }
    }

    /// Find a generator of the full prime-order group.  For prime n,
    /// any non-identity point IS a generator.
    fn any_nontrivial_point(aut: &J0CurveAut) -> Pt2 {
        let p_u = aut.p.to_u64_digits().1[0];
        let b_u = aut.b.to_u64_digits().1[0];
        for x in 0..p_u {
            let rhs = (x.wrapping_mul(x).wrapping_mul(x).wrapping_add(b_u)) % p_u;
            for y in 1..p_u {
                if (y * y) % p_u == rhs {
                    return Pt2::Aff(BigInt::from(x), BigInt::from(y));
                }
            }
        }
        panic!("no point found");
    }

    /// Canonicalisation: every aut-orbit element maps to the same
    /// canonical representative.
    #[test]
    fn canonicalisation_invariant_on_orbit() {
        let aut = good_aut();
        // Verify β³ ≡ 1 (mod p), λ³ ≡ 1 (mod n), and both ≠ 1.
        assert_eq!(mod_pos(aut.beta.pow(3), &aut.p), BigInt::one());
        assert_eq!(mod_pos(aut.lambda.pow(3), &aut.n), BigInt::one());
        assert_ne!(aut.beta, BigInt::one());
        assert_ne!(aut.lambda, BigInt::one());

        let pt = any_nontrivial_point(&aut);
        let (canon_ref, _) = canonical_form(&pt, &aut);
        for &alpha in AutElt::ALL.iter() {
            let p_alpha = apply_aut(&pt, alpha, &aut);
            let (canon_alpha, _) = canonical_form(&p_alpha, &aut);
            assert_eq!(
                compare_pt(&canon_alpha, &canon_ref),
                std::cmp::Ordering::Equal,
                "canonical form not invariant under aut {:?}",
                alpha
            );
        }
    }

    /// Aut element composition + inverse identities.
    #[test]
    fn aut_group_axioms() {
        for &a in AutElt::ALL.iter() {
            // a · a^{-1} = id
            assert_eq!(a.compose(a.inv()), AutElt::Id);
            // a^{-1} · a = id
            assert_eq!(a.inv().compose(a), AutElt::Id);
        }
        // ω · ω = ω²
        assert_eq!(AutElt::Omega.compose(AutElt::Omega), AutElt::Omega2);
        // ω · ω² = id
        assert_eq!(AutElt::Omega.compose(AutElt::Omega2), AutElt::Id);
        // (-1) · ω = -ω
        assert_eq!(AutElt::Neg.compose(AutElt::Omega), AutElt::NegOmega);
    }

    /// Integer-action consistency: `α(P) = μ_α · P` numerically.
    /// Validates only on Z[ω]-stable subgroups (prime order ≡ 1 mod 3).
    #[test]
    fn integer_action_matches_point_action() {
        let aut = good_aut();
        let pt = any_nontrivial_point(&aut);
        for &alpha in AutElt::ALL.iter() {
            let via_aut = apply_aut(&pt, alpha, &aut);
            let mu = alpha.integer_action(&aut.lambda, &aut.n);
            let via_scalar = pt_scalar_mul(&pt, &mu, &aut.a, &aut.p);
            assert_eq!(
                compare_pt(&via_aut, &via_scalar),
                std::cmp::Ordering::Equal,
                "α={:?} mismatch on Z[ω]-stable group: aut={:?}, scalar={:?}",
                alpha,
                via_aut,
                via_scalar
            );
        }
    }

    /// Planted-DLP recovery on a j=0 prime-order curve where the
    /// `√6` aut-folding speedup is mathematically valid.
    #[test]
    fn folded_rho_recovers_planted_dlp() {
        let aut = good_aut();
        let g = any_nontrivial_point(&aut);
        let d_planted = BigInt::from(7);
        let h = pt_scalar_mul(&g, &d_planted, &aut.a, &aut.p);

        let opts = FoldedRhoOptions {
            max_iterations: 4096,
            max_restarts: 32,
            seed: Some(0xC0FFEEu64),
        };
        let result = aut_folded_rho_dlp(&g, &h, &aut, &opts);
        match result {
            Ok(sol) => {
                let check = pt_scalar_mul(&g, &sol.d, &aut.a, &aut.p);
                assert_eq!(
                    compare_pt(&check, &h),
                    std::cmp::Ordering::Equal,
                    "recovered d = {} does not satisfy d·G = h on n={}",
                    sol.d,
                    aut.n
                );
                // The recovered d is correct (verified via point match);
                // it may differ from the planted d by an Aut(E) factor
                // (e.g., d ≡ −d_planted, since (−1)·G generates the same
                // DLP), which is the expected behaviour of aut-folded rho.
                println!(
                    "    aut-folded rho: planted d = {}, recovered d = {}, iters = {}, restarts = {}",
                    d_planted, sol.d, sol.iterations, sol.restarts
                );
            }
            Err(e) => panic!("aut-folded rho failed: {}", e),
        }
    }

    /// **Headline empirical result**: measure the speedup of
    /// aut-folded rho vs unfolded rho on the same j=0 curve.
    /// Theory predicts `√6 ≈ 2.45×` faster.  We measure across
    /// many planted `d` values and compare mean iteration counts.
    #[test]
    #[ignore = "experimental: ~30 s of repeated rho runs; --ignored to opt in"]
    fn empirical_speedup_versus_unfolded_rho() {
        // Use a larger toy curve for the variance to average out.
        // p = 67 (≡ 1 mod 3), search for prime-order j=0 curve.
        let p_u = 67u64;
        let (b_u, n_u) = find_j0_prime_order_curve(p_u).expect("j=0 prime-order curve at p=67");
        let beta_u = primitive_cube_root_mod(p_u).unwrap();
        let lambda_u = primitive_cube_root_mod(n_u).unwrap();
        let aut = J0CurveAut {
            p: BigInt::from(p_u),
            a: BigInt::from(0),
            b: BigInt::from(b_u),
            n: BigInt::from(n_u),
            beta: BigInt::from(beta_u),
            lambda: BigInt::from(lambda_u),
        };
        let g = any_nontrivial_point(&aut);

        // Run aut-folded rho 30 times with different planted d, average iterations.
        let mut folded_total: u64 = 0;
        let mut folded_runs: u32 = 0;
        for d_seed in 1..=30u32 {
            let d_planted = BigInt::from(d_seed);
            let h = pt_scalar_mul(&g, &d_planted, &aut.a, &aut.p);
            let opts = FoldedRhoOptions {
                max_iterations: 4096,
                max_restarts: 8,
                seed: Some((d_seed as u64).wrapping_mul(0x9E37_79B9_7F4A_7C15)),
            };
            if let Ok(sol) = aut_folded_rho_dlp(&g, &h, &aut, &opts) {
                folded_total += sol.iterations;
                folded_runs += 1;
            }
        }
        let folded_mean = folded_total as f64 / folded_runs.max(1) as f64;
        let n_f = n_u as f64;
        // Expected number of walk steps to the first repeated point on a
        // set of size N is √(πN/2).  `iterations` counts Floyd
        // tortoise-and-hare iterations, which stop at the first multiple
        // of the cycle length past the tail, after about 1.03·√N of them
        // (Knuth, TAOCP vol. 2, §3.1), so the like-for-like expectation
        // for the measured count is the Floyd line.
        let rho_len_full = (std::f64::consts::PI * n_f / 2.0).sqrt();
        let rho_len_folded = rho_len_full / 6f64.sqrt(); // √(πn/12)
        const FLOYD_CONSTANT: f64 = 1.03;
        let floyd_full = FLOYD_CONSTANT * n_f.sqrt();
        let floyd_folded = FLOYD_CONSTANT * (n_f / 6.0).sqrt();

        println!();
        println!("=== Aut-folded rho empirical speedup ===");
        println!(
            "  Curve: p = {}, b = {}, n = {} (prime ≡ 1 mod 3)",
            p_u, b_u, n_u
        );
        println!("  β = {}, λ = {}", beta_u, lambda_u);
        println!("  Aut(E) = Z/6Z order 6");
        println!(
            "  Aut-folded mean iterations: {:.1} (over {} runs)",
            folded_mean, folded_runs
        );
        println!(
            "  Expected rho length √(πn/2), unfolded:        {:.1}",
            rho_len_full
        );
        println!(
            "  Expected rho length √(πn/12), aut-folded:     {:.1}",
            rho_len_folded
        );
        println!(
            "  Expected Floyd iterations 1.03·√n, unfolded:  {:.1}",
            floyd_full
        );
        println!(
            "  Expected Floyd iterations 1.03·√(n/6), folded: {:.1}",
            floyd_folded
        );
        println!(
            "  Measured folded / expected unfolded Floyd: {:.2} (1/√6 ≈ 0.41 if the fold pays in full)",
            folded_mean / floyd_full
        );
        println!(
            "  Measured folded / expected folded Floyd:   {:.2} (1.00 = on the Floyd expectation)",
            folded_mean / floyd_folded
        );
        println!();
        println!("  Honest interpretation:");
        println!("  - Recovery is mathematically correct (folded_rho_recovers_planted_dlp).");
        println!(
            "  - At n = {}, statistical variance dominates over the √6 speedup.",
            n_u
        );
        println!("  - The √6 advantage is asymptotic; appearing cleanly requires n ≫ 10⁴.");
        println!("  - This module ships the algorithm and CORRECTNESS validation;");
        println!("    cryptographic-scale benchmarking would require a curve where");
        println!("    point arithmetic itself is fast (e.g., the projective");
        println!("    constant-time secp256k1 backend in `ecc::secp256k1_point`).");
        // Sanity: aut-folded should not be wildly worse than unfolded rho at
        // this scale.  Allow 4× variance margin for prime-order n=73.
        assert!(
            folded_mean < 4.0 * floyd_full,
            "aut-folded mean {} should be ≤ 4× the unfolded Floyd expectation {}",
            folded_mean,
            floyd_full
        );
    }

    /// Apply-aut + canonical_form round-trip.
    #[test]
    fn apply_aut_canonicalises() {
        let aut = good_aut();
        let pt = any_nontrivial_point(&aut);
        let (canon, alpha) = canonical_form(&pt, &aut);
        let recomputed = apply_aut(&pt, alpha, &aut);
        assert_eq!(
            compare_pt(&recomputed, &canon),
            std::cmp::Ordering::Equal,
            "apply_aut(P, α) ≠ canonical(P)"
        );
    }

    // ── The walk before its engineering changes, kept to pin them ──────
    //
    // `aut_folded_rho_dlp` now canonicalises three points per Floyd
    // iteration instead of five, computes `β²` once, reads the bucket
    // off a limb and reduces with one remainder.  None of that may
    // change a returned value, so the original code is kept here,
    // condensed but step for step, and both are run on the same
    // instances.  The group law and `mod_inverse` it shares with the
    // new code are pinned against their originals in their own modules.

    fn mod_pos_textbook(x: BigInt, p: &BigInt) -> BigInt {
        ((x % p) + p) % p
    }

    fn apply_aut_reference(point: &Pt2, alpha: AutElt, aut: &J0CurveAut) -> Pt2 {
        let (sign, omega_pow) = alpha.encode();
        let beta_pow = match omega_pow {
            0 => BigInt::one(),
            1 => aut.beta.clone(),
            2 => mod_pos_textbook(&aut.beta * &aut.beta, &aut.p),
            _ => unreachable!(),
        };
        let with_omega = match point {
            Pt2::Inf => Pt2::Inf,
            Pt2::Aff(x, y) => Pt2::Aff(mod_pos_textbook(x * &beta_pow, &aut.p), y.clone()),
        };
        match with_omega {
            Pt2::Aff(x, y) if sign != 1 => Pt2::Aff(x, mod_pos_textbook(-y, &aut.p)),
            other => other,
        }
    }

    fn canonical_form_reference(point: &Pt2, aut: &J0CurveAut) -> (Pt2, AutElt) {
        let mut best_pt = apply_aut_reference(point, AutElt::Id, aut);
        let mut best_alpha = AutElt::Id;
        for &alpha in AutElt::ALL.iter().skip(1) {
            let candidate = apply_aut_reference(point, alpha, aut);
            if compare_pt(&candidate, &best_pt) == std::cmp::Ordering::Less {
                best_pt = candidate;
                best_alpha = alpha;
            }
        }
        (best_pt, best_alpha)
    }

    fn walk_bucket_reference(canon: &Pt2) -> u8 {
        match canon {
            Pt2::Inf => 0u8,
            Pt2::Aff(cx, _) => {
                let bytes = cx.to_signed_bytes_be();
                let last = bytes.last().copied().unwrap_or(0);
                (last as u32 % 3) as u8
            }
        }
    }

    type Outcome = Result<(BigInt, u64, u32, u64), &'static str>;

    fn outcome(r: Result<FoldedRhoSolution, &'static str>) -> Outcome {
        r.map(|s| {
            (
                s.d,
                s.iterations,
                s.restarts,
                s.effective_rho_factor.to_bits(),
            )
        })
    }

    fn aut_folded_rho_reference(
        g: &Pt2,
        h: &Pt2,
        aut: &J0CurveAut,
        opts: &FoldedRhoOptions,
    ) -> Result<FoldedRhoSolution, &'static str> {
        let n = &aut.n;
        if n.is_zero() || n.is_one() {
            return Err("group order must be ≥ 2");
        }
        let mut rng: StdRng = match opts.seed {
            Some(s) => StdRng::seed_from_u64(s),
            None => StdRng::seed_from_u64(0xFADE_F00D_BABE_BEEFu64),
        };
        let mut total_iters: u64 = 0;
        let curve_a = &aut.a;
        let p_mod = &aut.p;
        let step = |x: &Pt2, a: &BigInt, b: &BigInt| -> (Pt2, BigInt, BigInt) {
            let (canon, _) = canonical_form_reference(x, aut);
            match walk_bucket_reference(&canon) {
                0 => {
                    let nx = pt_add(x, g, curve_a, p_mod);
                    (nx, mod_pos_textbook(a + BigInt::one(), n), b.clone())
                }
                1 => {
                    let nx = pt_add(x, h, curve_a, p_mod);
                    (nx, a.clone(), mod_pos_textbook(b + BigInt::one(), n))
                }
                _ => {
                    let nx = pt_double(x, curve_a, p_mod);
                    let na = mod_pos_textbook(a * BigInt::from(2), n);
                    let nb = mod_pos_textbook(b * BigInt::from(2), n);
                    (nx, na, nb)
                }
            }
        };
        for restart in 0..=opts.max_restarts {
            let (a0, b0) = if restart == 0 {
                (BigInt::one(), BigInt::zero())
            } else {
                (
                    rng.gen_bigint_range(&BigInt::zero(), n),
                    rng.gen_bigint_range(&BigInt::zero(), n),
                )
            };
            let pow_a = pt_scalar_mul(g, &a0, curve_a, p_mod);
            let pow_b = pt_scalar_mul(h, &b0, curve_a, p_mod);
            let x0 = pt_add(&pow_a, &pow_b, curve_a, p_mod);
            let (mut t, mut t_a, mut t_b) = (x0.clone(), a0.clone(), b0.clone());
            let (mut h_pt, mut h_a, mut h_b) = (x0, a0, b0);
            let mut iters: u64 = 0;
            let mut sterile = false;
            while iters < opts.max_iterations {
                (t, t_a, t_b) = step(&t, &t_a, &t_b);
                (h_pt, h_a, h_b) = step(&h_pt, &h_a, &h_b);
                (h_pt, h_a, h_b) = step(&h_pt, &h_a, &h_b);
                iters += 1;
                total_iters += 1;
                let (t_canon, t_alpha) = canonical_form_reference(&t, aut);
                let (h_canon, h_alpha) = canonical_form_reference(&h_pt, aut);
                if compare_pt(&t_canon, &h_canon) == std::cmp::Ordering::Equal {
                    let gamma = h_alpha.inv().compose(t_alpha);
                    let mu = gamma.integer_action(&aut.lambda, n);
                    let lhs = mod_pos_textbook((&mu * &t_a) - &h_a, n);
                    let rhs = mod_pos_textbook(&h_b - (&mu * &t_b), n);
                    if rhs.is_zero() || !rhs.gcd(n).is_one() {
                        sterile = true;
                        break;
                    }
                    let rhs_inv = crate::utils::mod_inverse(
                        &rhs.to_biguint().unwrap(),
                        &n.to_biguint().unwrap(),
                    )
                    .ok_or("rhs not invertible despite gcd=1 — internal inconsistency")?;
                    let d = mod_pos_textbook(&lhs * rhs_inv.to_bigint().unwrap(), n);
                    let check = pt_scalar_mul(g, &d, curve_a, p_mod);
                    if compare_pt(&check, h) == std::cmp::Ordering::Equal {
                        let factor = total_iters as f64 / (bigint_to_f64(n) / 6.0).sqrt();
                        return Ok(FoldedRhoSolution {
                            d,
                            iterations: total_iters,
                            restarts: restart,
                            effective_rho_factor: factor,
                        });
                    }
                    sterile = true;
                    break;
                }
            }
            if !sterile {
                return Err("rho exceeded max_iterations without finding a collision");
            }
        }
        Err("aut-folded rho exhausted max_restarts on sterile collisions")
    }

    /// The perfbench instance: `y² = x³ + 2` over a 25-bit prime, with
    /// `β` and `λ` matched so that `[λ]G = (β·x, y)`.
    fn aut_p25() -> (J0CurveAut, Pt2) {
        let aut = J0CurveAut {
            p: BigInt::from(33_756_013u64),
            a: BigInt::from(0),
            b: BigInt::from(2),
            n: BigInt::from(33_750_391u64),
            beta: BigInt::from(13_339_116u64),
            lambda: BigInt::from(25_380_340u64),
        };
        let g = Pt2::Aff(BigInt::from(8_339_409u64), BigInt::from(9_189_288u64));
        (aut, g)
    }

    #[test]
    fn mod_pos_matches_the_textbook_form() {
        let mut rng = StdRng::seed_from_u64(0x006d_6f64_5f70_6f73);
        for _ in 0..2000 {
            let bits = 1 + rng.gen_range(0..140u64);
            let x = rng.gen_bigint(bits);
            let bits = 1 + rng.gen_range(0..70u64);
            let mut p = rng.gen_bigint(bits);
            if p.is_zero() {
                p = BigInt::one();
            }
            for p in [p.clone(), -p] {
                assert_eq!(
                    mod_pos(x.clone(), &p),
                    mod_pos_textbook(x.clone(), &p),
                    "x = {x}, p = {p}"
                );
            }
        }
    }

    #[test]
    fn canonical_form_matches_applying_each_automorphism() {
        let mut rng = StdRng::seed_from_u64(0x0063_616e_6f6e);
        let (big, _) = aut_p25();
        // An unreduced `β` (the `BigInt` path) and a modulus above 2⁶³
        // (the word path's widest products); canonicalisation does not
        // need `β` to be a cube root for the two paths to be compared.
        let mut shifted = big.clone();
        shifted.beta = &big.beta + &big.p;
        let mut wide = big.clone();
        wide.p = BigInt::from(u64::MAX - 58);
        wide.beta = BigInt::from(0x9e37_79b9_7f4a_7c15u64);
        for aut in [good_aut(), big, shifted, wide] {
            let p = aut.p.clone();
            let mut points = vec![Pt2::Inf];
            // Every coordinate pair of a small field, then random and
            // unreduced ones: canonicalisation is a function of the
            // coordinates, on the curve or not.
            if p < BigInt::from(64) {
                let p_u = p.to_u64_digits().1[0];
                for x in 0..p_u {
                    for y in 0..p_u {
                        points.push(Pt2::Aff(BigInt::from(x), BigInt::from(y)));
                    }
                }
            }
            for _ in 0..2000 {
                let x = rng.gen_bigint_range(&BigInt::zero(), &p);
                let y = rng.gen_bigint_range(&BigInt::zero(), &p);
                points.push(Pt2::Aff(x.clone(), y.clone()));
                points.push(Pt2::Aff(x.clone(), BigInt::zero()));
                points.push(Pt2::Aff(&x + &p * 3, -&y));
                points.push(Pt2::Aff(-&x, &y + &p));
            }
            for pt in &points {
                let got = canonical_form(pt, &aut);
                assert_eq!(got, canonical_form_reference(pt, &aut), "{pt:?}");
                assert_eq!(walk_bucket(&got.0), walk_bucket_reference(&got.0));
            }
        }
    }

    /// The walk's exponent updates return `mod_pos_textbook(v + 1, n)`
    /// and `mod_pos_textbook(2v, n)` on and off the word path: reduced,
    /// negative and unreduced `v`, moduli from 2 through 2⁶⁴ − 1 (where
    /// the doubling carries out of the word) and above.
    #[test]
    fn exponent_updates_match_the_textbook_form() {
        let mut rng = StdRng::seed_from_u64(0x6578_706f);
        let mut moduli: Vec<BigInt> = [2u64, 3, 33_750_391, (1 << 63) + 1, u64::MAX]
            .into_iter()
            .map(BigInt::from)
            .collect();
        moduli.push(BigInt::from(u64::MAX) + 2);
        for _ in 0..50 {
            moduli.push(rng.gen_bigint_range(&BigInt::from(2), &(BigInt::one() << 70)));
        }
        for n in &moduli {
            let mut vs = vec![
                BigInt::zero(),
                n - 1,
                n - 2,
                n.clone(),
                -BigInt::one(),
                n * 3,
            ];
            for _ in 0..50 {
                vs.push(rng.gen_bigint_range(&BigInt::zero(), n));
                vs.push(rng.gen_bigint(80));
            }
            for v in &vs {
                let inc = mod_pos_textbook(v + BigInt::one(), n);
                let dbl = mod_pos_textbook(v * BigInt::from(2), n);
                assert_eq!(increment_mod(v, n), inc, "v = {v}, n = {n}");
                assert_eq!(double_mod(v, n), dbl, "v = {v}, n = {n}");
            }
        }
    }

    #[test]
    fn walk_bucket_matches_the_encoding() {
        let mut rng = StdRng::seed_from_u64(0x6275_636b);
        let mut xs: Vec<BigInt> = (-600..600).map(BigInt::from).collect();
        for _ in 0..4000 {
            let bits = 1 + rng.gen_range(0..200u64);
            xs.push(rng.gen_bigint(bits));
        }
        for x in xs {
            let pt = Pt2::Aff(x.clone(), BigInt::zero());
            assert_eq!(walk_bucket(&pt), walk_bucket_reference(&pt), "x = {x}");
        }
        assert_eq!(walk_bucket(&Pt2::Inf), walk_bucket_reference(&Pt2::Inf));
    }

    /// Every returned value — `d`, iterations, restarts and the bits of
    /// the rho factor, or the error — matches the original walk: on the
    /// perfbench curve, on the `p = 43` fixture (short walks, sterile
    /// collisions, restarts), with a mismatched `λ` (collisions whose
    /// `d` does not verify; with no restarts allowed, the exhausted-
    /// restarts error) and with too few iterations to collide.
    #[test]
    fn folded_rho_matches_the_original_walk() {
        let (aut, g) = aut_p25();
        let mut cases = Vec::new();
        let h = pt_scalar_mul(&g, &BigInt::from(1_234_567u64), &aut.a, &aut.p);
        cases.push((aut.clone(), g.clone(), h, 1 << 22, 16, 1u64));
        let small = good_aut();
        let sg = any_nontrivial_point(&small);
        for d in 1..12u64 {
            let h = pt_scalar_mul(&sg, &BigInt::from(d), &small.a, &small.p);
            cases.push((small.clone(), sg.clone(), h.clone(), 4096, 32, d));
            cases.push((small.clone(), sg.clone(), h.clone(), 2, 3, d));
            let mut skewed = small.clone();
            skewed.lambda = mod_pos(&small.lambda * &small.lambda, &small.n);
            cases.push((skewed.clone(), sg.clone(), h.clone(), 4096, 4, d));
            cases.push((skewed, sg.clone(), h, 4096, 0, d));
        }
        for (aut, g, h, max_iterations, max_restarts, seed) in cases {
            let opts = FoldedRhoOptions {
                max_iterations,
                max_restarts,
                seed: Some(seed),
            };
            assert_eq!(
                outcome(aut_folded_rho_dlp(&g, &h, &aut, &opts)),
                outcome(aut_folded_rho_reference(&g, &h, &aut, &opts)),
                "p = {}, seed = {seed}",
                aut.p
            );
        }
    }

    // ── The whole original stack, on word-sized fields of every width ───
    //
    // The tests above pin the walk to its original on the new group law
    // and `mod_inverse`, and pin those to their originals separately.
    // This copies the whole stack as it was — `utils::mod_inverse`, the
    // `cga_hnc` group law and the walk — and runs it next to the new
    // code on j = 0 curves whose moduli straddle each boundary of the
    // word paths: below and above 2³² (one-word products vs the `u128`
    // remainder), 2⁴⁰, 2⁶², above 2⁶³ (sums that carry out of the word),
    // within 2⁴⁰ of 2⁶⁴, and above 2⁶⁴ (`BigInt` only).  Each curve has
    // a prime-order subgroup of 16 or 17 bits, so every walk collides
    // within a few hundred iterations and the iteration count pins the
    // trajectory.
    mod original_stack {
        use super::super::{
            bigint_to_f64, compare_pt, AutElt, FoldedRhoOptions, FoldedRhoSolution, J0CurveAut,
        };
        use crate::cryptanalysis::cga_hnc::Pt2;
        use num_bigint::{BigInt, BigUint, RandBigInt, Sign, ToBigInt};
        use num_integer::Integer;
        use num_traits::{One, Zero};
        use rand::rngs::StdRng;
        use rand::SeedableRng;

        pub fn mod_inverse(a: &BigUint, m: &BigUint) -> Option<BigUint> {
            if a.is_zero() {
                return None;
            }
            let a_i = BigInt::from_biguint(Sign::Plus, a.clone());
            let m_i = BigInt::from_biguint(Sign::Plus, m.clone());
            let (mut old_r, mut r) = (a_i.clone(), m_i.clone());
            let (mut old_s, mut s) = (BigInt::one(), BigInt::zero());
            while !r.is_zero() {
                let q = &old_r / &r;
                let tmp = old_r - &q * &r;
                old_r = r;
                r = tmp;
                let tmp = old_s - q * &s;
                old_s = s;
                s = tmp;
            }
            if old_r != BigInt::one() && old_r != BigInt::from(-1i32) {
                return None;
            }
            let result = ((old_s % &m_i) + &m_i) % &m_i;
            result.to_biguint()
        }

        fn mod_pos(x: BigInt, p: &BigInt) -> BigInt {
            ((x % p) + p) % p
        }

        fn modular_inverse(x: &BigInt, p: &BigInt) -> Option<BigInt> {
            let x_pos = mod_pos(x.clone(), p);
            let xu = x_pos.to_biguint()?;
            let pu = p.to_biguint()?;
            let inv_u = mod_inverse(&xu, &pu)?;
            Some(inv_u.to_bigint().unwrap())
        }

        pub fn pt_double(p: &Pt2, a: &BigInt, p_mod: &BigInt) -> Pt2 {
            match p {
                Pt2::Inf => Pt2::Inf,
                Pt2::Aff(x, y) => {
                    if y.is_zero() {
                        return Pt2::Inf;
                    }
                    let two_y = mod_pos(BigInt::from(2) * y, p_mod);
                    let inv = match modular_inverse(&two_y, p_mod) {
                        Some(v) => v,
                        None => return Pt2::Inf,
                    };
                    let lam = mod_pos((BigInt::from(3) * x.pow(2) + a) * inv, p_mod);
                    let x3 = mod_pos(lam.pow(2) - BigInt::from(2) * x, p_mod);
                    let y3 = mod_pos(&lam * (x - &x3) - y, p_mod);
                    Pt2::Aff(x3, y3)
                }
            }
        }

        pub fn pt_add(p: &Pt2, q: &Pt2, a: &BigInt, p_mod: &BigInt) -> Pt2 {
            match (p, q) {
                (Pt2::Inf, x) | (x, Pt2::Inf) => x.clone(),
                (Pt2::Aff(x1, y1), Pt2::Aff(x2, y2)) => {
                    if x1 == x2 {
                        if y1 == y2 {
                            return pt_double(p, a, p_mod);
                        }
                        return Pt2::Inf;
                    }
                    let dx = mod_pos(x2 - x1, p_mod);
                    let inv = match modular_inverse(&dx, p_mod) {
                        Some(v) => v,
                        None => return Pt2::Inf,
                    };
                    let lam = mod_pos((y2 - y1) * inv, p_mod);
                    let x3 = mod_pos(lam.pow(2) - x1 - x2, p_mod);
                    let y3 = mod_pos(&lam * (x1 - &x3) - y1, p_mod);
                    Pt2::Aff(x3, y3)
                }
            }
        }

        pub fn pt_scalar_mul(p: &Pt2, k: &BigInt, a: &BigInt, p_mod: &BigInt) -> Pt2 {
            let mut result = Pt2::Inf;
            let mut addend = p.clone();
            let k_abs = k.magnitude().clone();
            for i in 0..k_abs.bits() {
                if k_abs.bit(i) {
                    result = pt_add(&result, &addend, a, p_mod);
                }
                addend = pt_double(&addend, a, p_mod);
            }
            if k.sign() == Sign::Minus {
                match result {
                    Pt2::Aff(x, y) => Pt2::Aff(x, mod_pos(-y, p_mod)),
                    Pt2::Inf => Pt2::Inf,
                }
            } else {
                result
            }
        }

        fn apply_aut(point: &Pt2, alpha: AutElt, aut: &J0CurveAut) -> Pt2 {
            let (sign, omega_pow) = alpha.encode();
            let beta_pow = match omega_pow {
                0 => BigInt::one(),
                1 => aut.beta.clone(),
                2 => mod_pos(&aut.beta * &aut.beta, &aut.p),
                _ => unreachable!(),
            };
            let with_omega = match point {
                Pt2::Inf => Pt2::Inf,
                Pt2::Aff(x, y) => {
                    let x_new = mod_pos(x * &beta_pow, &aut.p);
                    Pt2::Aff(x_new, y.clone())
                }
            };
            if sign == 1 {
                with_omega
            } else {
                match with_omega {
                    Pt2::Inf => Pt2::Inf,
                    Pt2::Aff(x, y) => Pt2::Aff(x, mod_pos(-y, &aut.p)),
                }
            }
        }

        pub fn canonical_form(point: &Pt2, aut: &J0CurveAut) -> (Pt2, AutElt) {
            let mut best_pt = apply_aut(point, AutElt::Id, aut);
            let mut best_alpha = AutElt::Id;
            for &alpha in AutElt::ALL.iter().skip(1) {
                let candidate = apply_aut(point, alpha, aut);
                if compare_pt(&candidate, &best_pt) == std::cmp::Ordering::Less {
                    best_pt = candidate;
                    best_alpha = alpha;
                }
            }
            (best_pt, best_alpha)
        }

        pub fn aut_folded_rho_dlp(
            g: &Pt2,
            h: &Pt2,
            aut: &J0CurveAut,
            opts: &FoldedRhoOptions,
        ) -> Result<FoldedRhoSolution, &'static str> {
            let n = &aut.n;
            if n.is_zero() || n.is_one() {
                return Err("group order must be ≥ 2");
            }
            let mut rng: StdRng = match opts.seed {
                Some(s) => StdRng::seed_from_u64(s),
                None => StdRng::seed_from_u64(0xFADE_F00D_BABE_BEEFu64),
            };
            let mut total_iters: u64 = 0;
            let curve_a = &aut.a;
            let p_mod = &aut.p;
            let step = |x: &Pt2, a: &BigInt, b: &BigInt| -> (Pt2, BigInt, BigInt) {
                let (canon, _) = canonical_form(x, aut);
                let bucket = match &canon {
                    Pt2::Inf => 0u8,
                    Pt2::Aff(cx, _) => {
                        let bytes = cx.to_signed_bytes_be();
                        let last = bytes.last().copied().unwrap_or(0);
                        (last as u32 % 3) as u8
                    }
                };
                match bucket {
                    0 => {
                        let nx = pt_add(x, g, curve_a, p_mod);
                        let na = mod_pos(a + BigInt::one(), n);
                        (nx, na, b.clone())
                    }
                    1 => {
                        let nx = pt_add(x, h, curve_a, p_mod);
                        let nb = mod_pos(b + BigInt::one(), n);
                        (nx, a.clone(), nb)
                    }
                    _ => {
                        let nx = pt_double(x, curve_a, p_mod);
                        let na = mod_pos(a * BigInt::from(2), n);
                        let nb = mod_pos(b * BigInt::from(2), n);
                        (nx, na, nb)
                    }
                }
            };
            for restart in 0..=opts.max_restarts {
                let (a0, b0) = if restart == 0 {
                    (BigInt::one(), BigInt::zero())
                } else {
                    (
                        rng.gen_bigint_range(&BigInt::zero(), n),
                        rng.gen_bigint_range(&BigInt::zero(), n),
                    )
                };
                let pow_a = pt_scalar_mul(g, &a0, curve_a, p_mod);
                let pow_b = pt_scalar_mul(h, &b0, curve_a, p_mod);
                let x0 = pt_add(&pow_a, &pow_b, curve_a, p_mod);
                let mut t = x0.clone();
                let mut t_a = a0.clone();
                let mut t_b = b0.clone();
                let mut h_pt = x0;
                let mut h_a = a0;
                let mut h_b = b0;
                let mut iters: u64 = 0;
                let mut sterile = false;
                while iters < opts.max_iterations {
                    let (nt, na, nb) = step(&t, &t_a, &t_b);
                    t = nt;
                    t_a = na;
                    t_b = nb;
                    let (nh, nha, nhb) = step(&h_pt, &h_a, &h_b);
                    h_pt = nh;
                    h_a = nha;
                    h_b = nhb;
                    let (nh, nha, nhb) = step(&h_pt, &h_a, &h_b);
                    h_pt = nh;
                    h_a = nha;
                    h_b = nhb;
                    iters += 1;
                    total_iters += 1;
                    let (t_canon, t_alpha) = canonical_form(&t, aut);
                    let (h_canon, h_alpha) = canonical_form(&h_pt, aut);
                    if compare_pt(&t_canon, &h_canon) == std::cmp::Ordering::Equal {
                        let gamma = h_alpha.inv().compose(t_alpha);
                        let mu = gamma.integer_action(&aut.lambda, n);
                        let lhs = mod_pos((&mu * &t_a) - &h_a, n);
                        let rhs = mod_pos(&h_b - (&mu * &t_b), n);
                        if rhs.is_zero() {
                            sterile = true;
                            break;
                        }
                        let g_factor = rhs.gcd(n);
                        if !g_factor.is_one() {
                            sterile = true;
                            break;
                        }
                        let rhs_u = rhs.to_biguint().expect("non-zero positive after mod_pos");
                        let n_u = n.to_biguint().expect("n positive");
                        let rhs_inv_u = mod_inverse(&rhs_u, &n_u)
                            .ok_or("rhs not invertible despite gcd=1 — internal inconsistency")?;
                        let rhs_inv = rhs_inv_u.to_bigint().expect("biguint→bigint");
                        let d = mod_pos(&lhs * &rhs_inv, n);
                        let check = pt_scalar_mul(g, &d, curve_a, p_mod);
                        if compare_pt(&check, h) == std::cmp::Ordering::Equal {
                            let n_f64 = bigint_to_f64(n);
                            let expected = (n_f64 / 6.0).sqrt();
                            let factor = total_iters as f64 / expected;
                            return Ok(FoldedRhoSolution {
                                d,
                                iterations: total_iters,
                                restarts: restart,
                                effective_rho_factor: factor,
                            });
                        }
                        sterile = true;
                        break;
                    }
                }
                if !sterile {
                    return Err("rho exceeded max_iterations without finding a collision");
                }
            }
            Err("aut-folded rho exhausted max_restarts on sterile collisions")
        }
    }

    #[test]
    fn folded_rho_matches_the_original_stack_across_word_widths() {
        // (p, b, n, β, λ, G.x, G.y): y² = x³ + b with a subgroup of prime
        // order n ≡ 1 (mod 3), λ matched to β so that [λ]G = (β·x, y).
        // Found offline (Cornacchia for the six j = 0 traces, then a
        // random point times the cofactor); checked below.
        #[rustfmt::skip]
        let curves: [(u128, u64, u64, u128, u64, u128, u128); 7] = [
            (2_790_913_597, 1, 114_967, 2_318_331_837, 39_400,
             1_565_400_886, 2_021_363_098),
            (5_486_869_291, 3, 85_081, 2_252_878_623, 13_559,
             3_891_712_341, 1_451_530_097),
            (1_718_933_335_831, 4, 63_541, 334_881_807_347, 40_395,
             1_301_312_732_909, 426_535_702_432),
            (6_681_231_359_065_941_163, 16, 140_317, 4_348_341_793_990_554_497, 110_705,
             2_591_368_914_137_066_277, 2_655_452_393_404_747_067),
            (15_532_268_153_442_727_957, 2, 77_863, 11_169_005_699_780_753_580, 35_062,
             10_325_685_930_842_972_537, 14_946_954_999_118_537_943),
            (18_446_743_996_931_373_379, 2, 44_179, 8_855_494_519_501_363_420, 9_675,
             1_675_201_009_986_212_036, 3_283_819_915_291_178_453),
            (43_031_671_274_336_716_483, 2, 130_693, 21_311_858_547_619_077_642, 101_254,
             1_670_257_532_644_218_207, 28_209_223_485_156_684_719),
        ];
        let (p25, g25) = aut_p25();
        let mut instances: Vec<(J0CurveAut, Pt2)> = vec![(p25, g25)];
        for &(p, b, n, beta, lambda, gx, gy) in &curves {
            let aut = J0CurveAut {
                p: BigInt::from(p),
                a: BigInt::zero(),
                b: BigInt::from(b),
                n: BigInt::from(n),
                beta: BigInt::from(beta),
                lambda: BigInt::from(lambda),
            };
            let g = Pt2::Aff(BigInt::from(gx), BigInt::from(gy));
            assert_eq!(
                original_stack::pt_scalar_mul(&g, &aut.n, &aut.a, &aut.p),
                Pt2::Inf,
                "n·G at p = {p}"
            );
            assert_eq!(
                original_stack::pt_scalar_mul(&g, &aut.lambda, &aut.a, &aut.p),
                Pt2::Aff(
                    mod_pos(BigInt::from(gx) * &aut.beta, &aut.p),
                    BigInt::from(gy)
                ),
                "[λ]G at p = {p}"
            );
            instances.push((aut, g));
        }
        let mut rng = StdRng::seed_from_u64(0x7265_7669_6577);
        for (i, (aut, g)) in instances.iter().enumerate() {
            let p = &aut.p;
            let mut skewed = aut.clone();
            skewed.lambda = mod_pos(&aut.lambda * &aut.lambda, &aut.n);
            // `G` with an unreduced x (the `BigInt` fallbacks), and `∞`.
            let g_wide = match g {
                Pt2::Aff(x, y) => Pt2::Aff(x + p, y.clone()),
                Pt2::Inf => unreachable!(),
            };
            // The perfbench curve's walks are a hundred times longer.
            let seeds = if i == 0 { 1 } else { 3 };
            let mut solved = 0;
            for seed in 0..seeds {
                let d = rng.gen_bigint_range(&BigInt::one(), &aut.n);
                let h = original_stack::pt_scalar_mul(g, &d, &aut.a, p);
                let h_neg_y = match &h {
                    Pt2::Aff(x, y) => Pt2::Aff(x.clone(), y - p),
                    Pt2::Inf => Pt2::Inf,
                };
                let cases = [
                    (aut, g, &h, 1u64 << 16, 8u32),
                    (aut, &g_wide, &h, 1 << 16, 4),
                    (aut, g, &h_neg_y, 1 << 16, 4),
                    (&skewed, g, &h, 1 << 16, 3),
                    (aut, g, &h, 7, 2),
                    (aut, g, &h, 0, 1),
                    (aut, &Pt2::Inf, &h, 64, 1),
                    (aut, g, &Pt2::Inf, 64, 1),
                ];
                for (aut, g, h, max_iterations, max_restarts) in cases {
                    let opts = FoldedRhoOptions {
                        max_iterations,
                        max_restarts,
                        seed: Some(seed),
                    };
                    let got = outcome(aut_folded_rho_dlp(g, h, aut, &opts));
                    assert_eq!(
                        got,
                        outcome(original_stack::aut_folded_rho_dlp(g, h, aut, &opts)),
                        "p = {p}, d = {d}, seed = {seed}, g = {g:?}, h = {h:?}, \
                         max_iterations = {max_iterations}"
                    );
                    solved += u64::from(got.is_ok_and(|(found, ..)| found == d));
                }
            }
            // Not vacuous: the matched walks find the planted logarithm.
            assert!(solved >= seeds, "p = {p}: {solved} walks solved");
            // Canonical forms and the group law on this curve's points.
            let mut pt = g.clone();
            for _ in 0..200 {
                assert_eq!(
                    canonical_form(&pt, aut),
                    original_stack::canonical_form(&pt, aut)
                );
                let k = rng.gen_bigint_range(&BigInt::zero(), &aut.n);
                let q = original_stack::pt_scalar_mul(g, &k, &aut.a, p);
                assert_eq!(
                    pt_add(&pt, &q, &aut.a, p),
                    original_stack::pt_add(&pt, &q, &aut.a, p)
                );
                assert_eq!(
                    pt_scalar_mul(&pt, &k, &aut.a, p),
                    original_stack::pt_scalar_mul(&pt, &k, &aut.a, p)
                );
                pt = original_stack::pt_double(&pt, &aut.a, p);
                assert_eq!(
                    pt_double(&q, &aut.a, p),
                    original_stack::pt_double(&q, &aut.a, p)
                );
            }
        }
    }
}
